/* From Uiverse.io by reshades - Tags: card, editor, code, vscode */
.__UIV_SCOPE__ .card {
  width: 250px;
  height: 254px;
  background: #121212;
  border-radius: 10px;
  border: 1px #212121 solid;
}

.__UIV_SCOPE__ .card hr {
  color: #313131;
  margin-top: -3.5px
}

.__UIV_SCOPE__ .content {
  color: #8e8e8e;
  margin-left: 0.3em;
}

.__UIV_SCOPE__ .c1 {
  color: rgb(55, 91, 158)
}

.__UIV_SCOPE__ .c2 {
  color: rgb(55, 158, 150)
}

.__UIV_SCOPE__ .c3 {
  color: rgb(158, 151, 55)
}

.__UIV_SCOPE__ .c4 {
  color: rgb(88, 158, 55)
}

.__UIV_SCOPE__ .comment {
  opacity: 50%
}

.__UIV_SCOPE__ .title {
  color: #e8e8e8;
  font-size: small;
  float: left;
  margin-left: 0.6em;
  margin-top: 0.6em;
}

.__UIV_SCOPE__ .top {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  font-size: 21px;
  font-weight: 450;
  background-color: #121212;
  width: 100%;
  text-align: right;
  border-radius: 10px
}

.__UIV_SCOPE__ .topfix {
  background-color: #121212;
  width: 100%;
  height: 1em;
  margin-top: -1em;
}

.__UIV_SCOPE__ button {
  width: 40px;
  height: 35px;
  margin-left: -5px;
  border: 0;
  outline: 0;
  background: transparent;
  transition: 0.2s;
}

.__UIV_SCOPE__ button svg path, 
.__UIV_SCOPE__ button svg rect, 
.__UIV_SCOPE__ button svg polygon {
  fill: #ffffff;
}

.__UIV_SCOPE__ button svg {
  width: 10px;
  height: 10px;
}

.__UIV_SCOPE__ .close:hover {
  background-color: #ffffff10;
}

.__UIV_SCOPE__ .maximize:hover {
  background-color: #ffffff10;
}

.__UIV_SCOPE__ .minimize:hover {
  background-color: #ffffff10;
}
